<script setup>
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import { RefreshCw, ArrowUpRight, ChevronLeft, ChevronRight, Wallet, ChartNoAxesCombined, ReceiptText, X } from 'lucide-vue-next'
import { api } from '../api'
import { beijingDay, financeReport, financeTime } from '../ejh-finance'
import Pagination from './Pagination.vue'
const data=ref(null),history=ref({}),busy=ref(false),error=ref(''),updated=ref('')
const mode=ref('all'),date=ref(beijingDay()),kind=ref(''),query=ref(''),dayFilter=ref(''),page=ref(1),pageSize=ref(10),detail=ref(null)
let disposed=false,timer
const labels={opening:'开卡费',reversal:'授权撤销费',recharge:'充值手续费',consumption:'消费 R'}
const report=computed(()=>financeReport(data.value||{},history.value,mode.value,date.value))
const summary=computed(()=>report.value.summary)
const overview=computed(()=>report.value.overview)
const trends=computed(()=>report.value.rows.filter(r=>r.day!=='未分期历史').slice(0,31).reverse())
const trendMax=computed(()=>({usd:Math.max(1,...trends.value.map(r=>Number(r.usd))),r:Math.max(1,...trends.value.map(r=>r.r||0))}))
const filtered=computed(()=>report.value.events.filter(e=>(!kind.value||e.kind===kind.value)&&(!dayFilter.value||(e.at===null?'未分期历史':mode.value==='all'?beijingDay(e.at).slice(0,7):beijingDay(e.at))===dayFilter.value)&&[e.email,e.card,e.reference,e.note].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())))
const visible=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value))
const when=value=>{const n=typeof value==='number'?value:financeTime(value);return n===null?'未分期历史':new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(n)}
const numR=value=>value===null?'—':Number(value).toFixed(4)
watch([mode,date],()=>{page.value=1;dayFilter.value='';detail.value=null})
watch([kind,query,dayFilter,pageSize],()=>page.value=1)
watch(()=>filtered.value.length,()=>{page.value=Math.min(page.value,Math.max(1,Math.ceil(filtered.value.length/pageSize.value)))})
async function load(){
 if(busy.value)return
 busy.value=true;error.value=''
 try{const [a,b]=await Promise.all([api('/api/ejh/dashboard'),api('/api/ejh/finance')]);if(!disposed){data.value=a;history.value=b;updated.value=a.server_time||new Date().toISOString()}}
 catch(e){if(!disposed)error.value=e.message}
 finally{if(!disposed)busy.value=false}
}
function shift(direction){
 const at=financeTime(date.value+'T12:00:00+08:00');if(at===null)return
 if(mode.value==='month'){const d=new Date(at+8*3600000);d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+direction);date.value=beijingDay(d.getTime()-8*3600000)}
 else date.value=beijingDay(at+direction*(mode.value==='week'?7:1)*86400000)
}
function showDay(day){dayFilter.value=day;document.querySelector('#ejh-finance-details')?.scrollIntoView({behavior:'smooth',block:'start'})}
onMounted(()=>{load();timer=setInterval(load,30000)})
onBeforeUnmount(()=>{disposed=true;clearInterval(timer)})
</script>
<template>
 <div class="finance-page">
  <header class="finance-heading"><div><span class="eyebrow">EJH · COST & USAGE</span><h1>成本统计</h1><p>花了多少，消耗多少，一眼看清。</p></div><button class="btn ghost" :disabled="busy" @click="load"><RefreshCw :size="14" :class="{spin:busy}"/>{{busy?'更新中…':'刷新统计'}}</button></header>
  <div class="period-toolbar"><div class="period-switch" role="group" aria-label="统计周期"><button v-for="[value,label] in [['day','每天'],['week','每周'],['month','每月'],['all','全部']]" :key="value" :aria-pressed="mode===value" :class="{active:mode===value}" @click="mode=value">{{label}}</button></div><div v-if="mode!=='all'" class="date-controls"><button class="icon-button" aria-label="上一期" @click="shift(-1)"><ChevronLeft :size="16"/></button><input v-model="date" type="date" aria-label="统计日期"/><button class="icon-button" aria-label="下一期" @click="shift(1)"><ChevronRight :size="16"/></button><button class="today" @click="date=beijingDay()">今天</button></div><span class="period-label">{{report.range.label}} · 北京时间</span></div>
  <div v-if="error" class="finance-error" role="alert">{{data?'刷新失败，保留上次数据：':''}}{{error}} <button @click="load">重试</button></div>
  <div v-if="!data" class="finance-loading" role="status">{{busy?'正在读取费用与消费记录…':'暂无可用数据'}}</div>
  <template v-else>
   <div v-if="history.recording?.error" class="finance-error" role="alert">历史记录保存失败：{{history.recording.error}}。现有统计保留，后台将重试。</div>
   <div class="finance-heroes">
    <section class="hero cost"><div class="hero-label"><Wallet :size="17"/>本期费用合计 <span v-if="summary.missing">部分数据</span></div><div class="hero-number">{{summary.usd??'—'}} <small>USD</small></div><div class="hero-secondary">＋ {{summary.usdt}} <small>USDT 开卡费</small></div><p>授权撤销费 + 充值手续费；USDT 单列</p></section>
    <section class="hero usage"><div class="hero-label"><ChartNoAxesCombined :size="17"/>本期消费总额</div><div class="hero-number">{{numR(summary.r)}} <small>R</small></div><div class="hero-secondary">{{mode==='all'?'累计用户消耗':'本期已采集增量'}}</div><p>{{mode==='all'?'账号去重，已留存的历史消耗持续保留':'按采集日期统计，不把历史累计记为当天消费'}}</p></section>
    <section class="hero loss"><div class="hero-label"><ReceiptText :size="17"/>当前实际损耗 <span>资金差额{{overview.estimated?' · 估算':''}}</span></div><div class="hero-number">{{overview.loss??'—'}} <small>USD</small></div><div class="hero-secondary">实际到账 {{overview.net??'—'}} <small>USD</small></div><p>{{overview.lossReasons.join('；')||'当前累计值，独立于左侧所选周期'}}</p></section>
   </div>
   <div class="finance-breakdown">
    <button :class="{selected:kind==='reversal'}" @click="kind=kind==='reversal'?'':'reversal'"><span>授权撤销费 <ArrowUpRight :size="14"/></span><strong>{{summary.reversalUSD}} <em>USD</em></strong><small>{{summary.original.map(r=>r.amount+' '+r.currency).join(' / ')||'无已知撤销费用'}} · 按 {{data.reversal_fee_percent??6}}%</small></button>
    <button :class="{selected:kind==='opening'}" @click="kind=kind==='opening'?'':'opening'"><span>开卡费 <ArrowUpRight :size="14"/></span><strong>{{summary.usdt}} <em>USDT</em></strong><small>{{summary.opening}} 张 × 0.50 · 含已销卡</small></button>
    <button :class="{selected:kind==='recharge'}" @click="kind=kind==='recharge'?'':'recharge'"><span>充值手续费 <ArrowUpRight :size="14"/></span><strong>{{summary.rechargeUSD??'—'}} <em>USD</em></strong><small>充值金额 × 1% · 总账修正会同步调整</small></button>
   </div>
   <div v-if="report.baseline||report.undated||summary.missing||overview.consumption.missing" class="finance-notice"><span v-if="report.baseline">历史累计 {{numR(report.baseline)}} R 未分期，计入“全部”。 </span><span v-if="report.undated">{{report.undated}} 笔历史费用无日期，仅计入“全部”。 </span><span v-if="summary.missing">{{summary.missing}} 项数据待核实，合计不完整。 </span><span v-if="overview.consumption.missing">{{overview.consumption.missing}} 个账号消费尚未查询。 </span></div>
   <div class="finance-charts"><section v-for="[field,title,unit] in [['usd','费用趋势','USD'],['r','消费趋势','R']]" :key="field" class="finance-panel"><div class="panel-heading"><h2>{{title}}</h2><small>{{mode==='all'?'最近 31 个有记录的月份':'按日'}} · {{unit}}{{field==='usd'?' / USDT 开卡费见明细':''}}</small></div><div v-if="trends.length" class="trend-bars" :aria-label="title"><button v-for="row in trends" :key="row.day" class="trend-column" :title="row.day+'：'+row[field]+' '+unit" @click="showDay(row.day)"><span class="bar-track"><i :style="{height:Math.max(2,Math.abs(Number(row[field])||0)/trendMax[field]*100)+'%'}" :class="{usage:field==='r',negative:Number(row[field])<0}"></i></span><small>{{row.day.slice(mode==='all'?2:5)}}</small><strong>{{Number(row[field]||0).toFixed(2)}}</strong></button></div><div v-else class="chart-empty">本期暂无分期记录</div></section></div>
   <section class="finance-panel"><div class="panel-heading"><h2>{{mode==='all'?'按月汇总':'每日明细'}}</h2><small>点击日期查看对应记录</small></div><div class="finance-table"><table><thead><tr><th>日期</th><th>费用 USD</th><th>开卡费 USDT</th><th>消费 R</th><th>数据</th></tr></thead><tbody><tr v-for="row in report.rows" :key="row.day"><td><button class="text-link" @click="showDay(row.day)">{{row.day}}</button></td><td>{{row.usd}}</td><td>{{row.usdt}}</td><td>{{numR(row.r)}}</td><td>{{row.missing?'部分待核实':'已记录'}}</td></tr><tr v-if="!report.rows.length"><td colspan="5" class="empty">本期暂无记录</td></tr></tbody></table></div></section>
   <section id="ejh-finance-details" class="finance-panel"><div class="panel-heading"><h2>费用与消费明细 <small>{{filtered.length}} 条</small></h2><button v-if="dayFilter" class="text-link" @click="dayFilter=''">{{dayFilter}} ×</button></div><div class="detail-filters"><select v-model="kind" aria-label="明细类型"><option value="">全部类型</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select><input v-model="query" type="search" aria-label="搜索账号、卡片或流水" placeholder="搜索账号、卡片或流水"/></div><div class="finance-table"><table><thead><tr><th>时间</th><th>类型</th><th>卡片 / 账号</th><th>原币金额</th><th>折合 USD</th><th></th></tr></thead><tbody><tr v-for="entry in visible" :key="entry.id"><td>{{when(entry.at)}}</td><td><span class="entry-kind" :class="entry.kind">{{labels[entry.kind]}}</span></td><td>{{entry.email||entry.card||'—'}}</td><td>{{entry.amount===null?'待核实':entry.kind==='consumption'?numR(entry.amount):entry.amount}} {{entry.currency}}</td><td>{{entry.kind==='consumption'||entry.kind==='opening'?'—':entry.usd??'待核实'}}</td><td><button class="text-link" @click="detail=entry">详情</button></td></tr><tr v-if="!visible.length"><td colspan="6" class="empty">没有匹配的记录</td></tr></tbody></table></div><Pagination :page="page" :page-size="pageSize" :total="filtered.length" @update:page="page=$event" @update:page-size="pageSize=$event"/></section>
   <footer class="finance-footnote"><span>更新于 {{when(updated)}} · 读取已保存数据，每 30 秒更新</span><details><summary>统计说明与历史覆盖</summary><p>消费 R 使用 Pro 账号下游用户消耗。首次采集值作为未分期历史；之后的正向增量按北京时间采集日期入账，跨日采集不能还原每笔消费的发生时间。账号删除后保留已记录消耗。已有历史但没有采集记录的账号，消费可在“全部”查看。</p><p>开卡费用按成功开出的卡去重，0.50 USDT/张。授权撤销费按当前配置比例估算，原币转 USD 使用各卡初始开卡结算比例。USDT 不当作 USD 相加。周期费用可因总账修正出现负数；缺失记录不按零补齐。</p><p>实际损耗＝充值总额 − 1% 充值手续费 − EJH 账户余额 − 正常及销卡中卡片余额折合 USD − 在途卡内付款折合 USD。它已包含资金损耗，不再叠加费用明细。余额为各自最近一次查询值，损耗不代表卡台最终账单。</p><p>本期快照内损耗变化：{{report.lossChange??'暂不可计算'}} USD<span v-if="report.firstAt">（{{when(report.firstAt)}} 至 {{when(report.lastAt)}}）</span>。后台每分钟保留已保存余额的每日首末快照；没有完整期初记录时，不冒充整个周期的实际损耗。</p></details></footer>
  </template>
  <Teleport to="body"><div v-if="detail" class="modal-backdrop" @click.self="detail=null"><section class="finance-dialog" role="dialog" aria-modal="true" aria-label="费用与消费详情"><button class="icon-button" aria-label="关闭详情" @click="detail=null"><X :size="18"/></button><span class="eyebrow">{{labels[detail.kind]}}</span><h2>{{detail.amount??'待核实'}} {{detail.currency}}</h2><p v-if="detail.usd!==null&&detail.usd!==undefined">折合 {{detail.usd}} USD</p><dl><dt>时间</dt><dd>{{when(detail.at)}}</dd><dt v-if="detail.card">卡片</dt><dd v-if="detail.card">{{detail.card}}</dd><dt v-if="detail.email">账号</dt><dd v-if="detail.email">{{detail.email}}</dd><dt>记录编号</dt><dd>{{detail.reference||detail.id}}</dd></dl><p>{{detail.note}}</p></section></div></Teleport>
 </div>
</template>
<style scoped>
.finance-page{display:grid;gap:20px;color:var(--text);font-variant-numeric:tabular-nums}.finance-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}.eyebrow{font-size:10px;color:var(--green-strong);font-weight:600;letter-spacing:1.6px}.finance-heading h1{font-size:26px;letter-spacing:-.7px;margin:6px 0}.finance-heading p{color:var(--muted);font-size:12px;margin:0}.finance-heading .btn{display:flex;gap:7px;align-items:center}.period-toolbar{display:flex;gap:16px;align-items:center;flex-wrap:wrap;padding:8px;background:var(--surface);border:1px solid var(--line);border-radius:12px}.period-switch{display:flex;gap:3px;background:var(--bg);border-radius:8px;padding:3px}.period-switch button{padding:9px 19px;border-radius:6px;font-size:12px;color:var(--muted)}.period-switch .active{background:var(--green-strong);color:white}.date-controls{display:flex;align-items:center;gap:5px}.date-controls input{width:145px;padding:7px 8px;border:1px solid var(--line);border-radius:6px;background:var(--surface);font-size:12px}.today,.text-link{font-size:12px;color:var(--green-strong);padding:4px}.period-label{margin-left:auto;padding:0 10px;font-size:11px;color:var(--muted)}.finance-heroes{display:grid;grid-template-columns:1.15fr 1fr 1fr;gap:16px}.hero{padding:24px;border:1px solid var(--line);border-radius:14px;background:var(--surface);min-width:0}.hero.cost{background:var(--green-strong);color:white;border-color:transparent}.hero-label{display:flex;gap:8px;align-items:center;font-size:12px}.hero-label>span{margin-left:auto;font-size:10px;opacity:.65}.hero-number{font-size:38px;line-height:1.2;letter-spacing:-1px;font-weight:600;margin:22px 0 10px;overflow-wrap:anywhere}.hero-number small{font-size:13px;font-weight:400;letter-spacing:0;opacity:.65}.hero-secondary{font-size:16px}.hero-secondary small{font-size:11px;opacity:.7}.hero p{font-size:10px;line-height:1.7;opacity:.65;margin:16px 0 0}.usage .hero-number{color:var(--green-strong)}.finance-breakdown{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--surface)}.finance-breakdown>button{padding:18px 24px;text-align:left;min-width:0}.finance-breakdown>button+button{border-left:1px solid var(--line)}.finance-breakdown>button.selected{background:var(--green-bg)}.finance-breakdown span{font-size:11px;color:var(--muted);display:flex;justify-content:space-between}.finance-breakdown strong{display:block;font-size:24px;margin:10px 0 5px}.finance-breakdown em{font-style:normal;font-weight:400;font-size:11px;color:var(--muted)}.finance-breakdown small{font-size:10px;color:var(--muted)}.finance-notice{border-left:3px solid #d69b4c;background:var(--surface);padding:12px 16px;font-size:11px;line-height:1.7;color:var(--muted)}.finance-charts{display:grid;grid-template-columns:1fr 1fr;gap:16px}.finance-panel{border:1px solid var(--line);border-radius:12px;background:var(--surface);min-width:0;overflow:hidden}.panel-heading{display:flex;align-items:center;justify-content:space-between;padding:18px 20px;gap:12px}.panel-heading h2{font-size:14px;margin:0}.panel-heading small{font-size:10px;color:var(--muted);font-weight:400}.trend-bars{display:flex;gap:8px;padding:0 20px 18px;overflow:auto}.trend-column{flex:1;min-width:36px;max-width:100px;display:flex;flex-direction:column;align-items:center;gap:7px}.bar-track{height:100px;display:flex;width:100%;align-items:flex-end;justify-content:center;border-bottom:1px solid var(--line)}.bar-track i{display:block;width:65%;max-width:44px;background:#dcaa67;border-radius:4px 4px 0 0}.bar-track i.usage{background:var(--green-strong)}.bar-track i.negative{background:var(--muted)}.trend-column small{font-size:9px;color:var(--muted)}.trend-column strong{font-size:10px;font-weight:500}.chart-empty{height:155px;display:grid;place-items:center;color:var(--muted);font-size:12px}.finance-table{overflow:auto}.finance-table table{width:100%;border-collapse:collapse;font-size:12px}.finance-table th{text-align:left;font-size:10px;color:var(--muted);font-weight:500;background:var(--bg);padding:12px 20px;white-space:nowrap}.finance-table td{padding:13px 20px;border-top:1px solid var(--line);white-space:nowrap}.finance-table td:nth-child(n+2){font-variant-numeric:tabular-nums}.finance-table .empty{text-align:center;color:var(--muted);padding:28px}.detail-filters{display:flex;gap:10px;padding:0 20px 16px}.detail-filters select,.detail-filters input{border:1px solid var(--line);border-radius:6px;padding:8px 10px;background:var(--surface);font-size:12px;min-width:0}.detail-filters input{flex:1}.entry-kind{font-size:10px;padding:4px 7px;background:var(--green-bg);color:var(--green-strong);border-radius:4px}.entry-kind.reversal{color:#94651c;background:#b58c3614}.entry-kind.recharge{color:var(--muted);background:var(--bg)}.finance-footnote{display:flex;gap:20px;justify-content:space-between;font-size:10px;color:var(--muted);align-items:flex-start}.finance-footnote details{max-width:65%;line-height:1.8}.finance-footnote summary{cursor:pointer}.finance-footnote p{margin:10px 0}.finance-error{padding:14px;border:1px solid var(--red);border-radius:8px;color:var(--red);font-size:12px}.finance-error button{text-decoration:underline}.finance-loading{padding:80px 20px;text-align:center;color:var(--muted)}.finance-dialog{position:relative;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:30px;width:min(500px,calc(100vw - 32px));overflow-wrap:anywhere}.finance-dialog>.icon-button{position:absolute;right:14px;top:14px}.finance-dialog h2{margin:18px 0 8px;font-size:30px}.finance-dialog dl{display:grid;grid-template-columns:70px 1fr;gap:12px;font-size:12px;padding:20px 0;border-block:1px solid var(--line);margin:20px 0}.finance-dialog dt,.finance-dialog p{color:var(--muted);font-size:12px}.finance-dialog dd{margin:0}.spin{animation:finance-spin 1s linear infinite}@keyframes finance-spin{to{transform:rotate(360deg)}}@media(max-width:1100px){.hero-number{font-size:30px}.hero{padding:20px}.hero-label{flex-wrap:wrap}.hero-label>span{margin-left:0}.finance-charts{grid-template-columns:1fr}}@media(max-width:700px){.finance-heroes,.finance-breakdown{grid-template-columns:1fr}.finance-breakdown>button+button{border-left:0;border-top:1px solid var(--line)}.period-label{margin-left:0}.period-switch{width:100%}.period-switch button{flex:1}.finance-heading h1{font-size:23px}.finance-footnote{flex-direction:column}.finance-footnote details{max-width:100%}.detail-filters{flex-wrap:wrap}.detail-filters input{width:100%}.hero-number{font-size:36px}}
</style>
